CREATE TRIGGER "player_game_boxes_participant" BEFORE INSERT ON player_game_boxes WHEN NOT EXISTS (SELECT 1 FROM games WHERE game_id=NEW.game_id AND NEW.team_id IN (home_team_id,away_team_id)) BEGIN SELECT RAISE(ABORT,'team is not a game participant'); END;

CREATE TRIGGER "team_game_boxes_participant" BEFORE INSERT ON team_game_boxes WHEN NOT EXISTS (SELECT 1 FROM games WHERE game_id=NEW.game_id AND NEW.team_id IN (home_team_id,away_team_id)) BEGIN SELECT RAISE(ABORT,'team is not a game participant'); END;

CREATE TRIGGER "game_period_scores_participant" BEFORE INSERT ON game_period_scores WHEN NOT EXISTS (SELECT 1 FROM games WHERE game_id=NEW.game_id AND NEW.team_id IN (home_team_id,away_team_id)) BEGIN SELECT RAISE(ABORT,'team is not a game participant'); END;

CREATE TRIGGER "player_game_boxes_frozen_conflict" BEFORE INSERT ON player_game_boxes WHEN EXISTS(SELECT 1 FROM game_state_observations WHERE game_id=NEW.game_id AND is_final=1) AND EXISTS(SELECT 1 FROM player_game_boxes old WHERE old."game_id"=NEW."game_id" AND old."player_id"=NEW."player_id" AND ((old."team_id" IS NOT NULL AND NEW."team_id" IS NOT NULL AND old."team_id"<>NEW."team_id") OR (old."points" IS NOT NULL AND NEW."points" IS NOT NULL AND old."points"<>NEW."points") OR (old."fg_made" IS NOT NULL AND NEW."fg_made" IS NOT NULL AND old."fg_made"<>NEW."fg_made") OR (old."fg_attempted" IS NOT NULL AND NEW."fg_attempted" IS NOT NULL AND old."fg_attempted"<>NEW."fg_attempted") OR (old."three_made" IS NOT NULL AND NEW."three_made" IS NOT NULL AND old."three_made"<>NEW."three_made") OR (old."three_attempted" IS NOT NULL AND NEW."three_attempted" IS NOT NULL AND old."three_attempted"<>NEW."three_attempted") OR (old."ft_made" IS NOT NULL AND NEW."ft_made" IS NOT NULL AND old."ft_made"<>NEW."ft_made") OR (old."ft_attempted" IS NOT NULL AND NEW."ft_attempted" IS NOT NULL AND old."ft_attempted"<>NEW."ft_attempted") OR (old."offensive_rebounds" IS NOT NULL AND NEW."offensive_rebounds" IS NOT NULL AND old."offensive_rebounds"<>NEW."offensive_rebounds") OR (old."defensive_rebounds" IS NOT NULL AND NEW."defensive_rebounds" IS NOT NULL AND old."defensive_rebounds"<>NEW."defensive_rebounds") OR (old."assists" IS NOT NULL AND NEW."assists" IS NOT NULL AND old."assists"<>NEW."assists") OR (old."steals" IS NOT NULL AND NEW."steals" IS NOT NULL AND old."steals"<>NEW."steals") OR (old."blocks" IS NOT NULL AND NEW."blocks" IS NOT NULL AND old."blocks"<>NEW."blocks") OR (old."turnovers" IS NOT NULL AND NEW."turnovers" IS NOT NULL AND old."turnovers"<>NEW."turnovers") OR (old."fouls" IS NOT NULL AND NEW."fouls" IS NOT NULL AND old."fouls"<>NEW."fouls") OR (old."minutes_raw" IS NOT NULL AND NEW."minutes_raw" IS NOT NULL AND old."minutes_raw"<>NEW."minutes_raw") OR (old."plus_minus" IS NOT NULL AND NEW."plus_minus" IS NOT NULL AND old."plus_minus"<>NEW."plus_minus") OR (old."possessions_raw" IS NOT NULL AND NEW."possessions_raw" IS NOT NULL AND old."possessions_raw"<>NEW."possessions_raw") OR (old."defensive_fg_made" IS NOT NULL AND NEW."defensive_fg_made" IS NOT NULL AND old."defensive_fg_made"<>NEW."defensive_fg_made") OR (old."defensive_fg_attempted" IS NOT NULL AND NEW."defensive_fg_attempted" IS NOT NULL AND old."defensive_fg_attempted"<>NEW."defensive_fg_attempted") OR (old."defensive_points" IS NOT NULL AND NEW."defensive_points" IS NOT NULL AND old."defensive_points"<>NEW."defensive_points") OR (old."is_starter" IS NOT NULL AND NEW."is_starter" IS NOT NULL AND old."is_starter"<>NEW."is_starter") OR (old."in_use" IS NOT NULL AND NEW."in_use" IS NOT NULL AND old."in_use"<>NEW."in_use") OR (old."points_provenance" IS NOT NULL AND NEW."points_provenance" IS NOT NULL AND old."points_provenance"<>NEW."points_provenance"))) BEGIN SELECT RAISE(ABORT,'frozen game conflict; quarantine required'); END;

CREATE TRIGGER "team_game_boxes_frozen_conflict" BEFORE INSERT ON team_game_boxes WHEN EXISTS(SELECT 1 FROM game_state_observations WHERE game_id=NEW.game_id AND is_final=1) AND EXISTS(SELECT 1 FROM team_game_boxes old WHERE old."game_id"=NEW."game_id" AND old."team_id"=NEW."team_id" AND ((old."points" IS NOT NULL AND NEW."points" IS NOT NULL AND old."points"<>NEW."points") OR (old."fg_made" IS NOT NULL AND NEW."fg_made" IS NOT NULL AND old."fg_made"<>NEW."fg_made") OR (old."fg_attempted" IS NOT NULL AND NEW."fg_attempted" IS NOT NULL AND old."fg_attempted"<>NEW."fg_attempted") OR (old."three_made" IS NOT NULL AND NEW."three_made" IS NOT NULL AND old."three_made"<>NEW."three_made") OR (old."three_attempted" IS NOT NULL AND NEW."three_attempted" IS NOT NULL AND old."three_attempted"<>NEW."three_attempted") OR (old."ft_made" IS NOT NULL AND NEW."ft_made" IS NOT NULL AND old."ft_made"<>NEW."ft_made") OR (old."ft_attempted" IS NOT NULL AND NEW."ft_attempted" IS NOT NULL AND old."ft_attempted"<>NEW."ft_attempted") OR (old."offensive_rebounds" IS NOT NULL AND NEW."offensive_rebounds" IS NOT NULL AND old."offensive_rebounds"<>NEW."offensive_rebounds") OR (old."defensive_rebounds" IS NOT NULL AND NEW."defensive_rebounds" IS NOT NULL AND old."defensive_rebounds"<>NEW."defensive_rebounds") OR (old."assists" IS NOT NULL AND NEW."assists" IS NOT NULL AND old."assists"<>NEW."assists") OR (old."steals" IS NOT NULL AND NEW."steals" IS NOT NULL AND old."steals"<>NEW."steals") OR (old."blocks" IS NOT NULL AND NEW."blocks" IS NOT NULL AND old."blocks"<>NEW."blocks") OR (old."turnovers" IS NOT NULL AND NEW."turnovers" IS NOT NULL AND old."turnovers"<>NEW."turnovers") OR (old."fouls" IS NOT NULL AND NEW."fouls" IS NOT NULL AND old."fouls"<>NEW."fouls") OR (old."minutes_raw" IS NOT NULL AND NEW."minutes_raw" IS NOT NULL AND old."minutes_raw"<>NEW."minutes_raw") OR (old."plus_minus" IS NOT NULL AND NEW."plus_minus" IS NOT NULL AND old."plus_minus"<>NEW."plus_minus") OR (old."possessions_raw" IS NOT NULL AND NEW."possessions_raw" IS NOT NULL AND old."possessions_raw"<>NEW."possessions_raw") OR (old."fastbreak_points" IS NOT NULL AND NEW."fastbreak_points" IS NOT NULL AND old."fastbreak_points"<>NEW."fastbreak_points") OR (old."paint_points" IS NOT NULL AND NEW."paint_points" IS NOT NULL AND old."paint_points"<>NEW."paint_points") OR (old."second_chance_points" IS NOT NULL AND NEW."second_chance_points" IS NOT NULL AND old."second_chance_points"<>NEW."second_chance_points") OR (old."points_off_turnovers" IS NOT NULL AND NEW."points_off_turnovers" IS NOT NULL AND old."points_off_turnovers"<>NEW."points_off_turnovers") OR (old."largest_lead" IS NOT NULL AND NEW."largest_lead" IS NOT NULL AND old."largest_lead"<>NEW."largest_lead"))) BEGIN SELECT RAISE(ABORT,'frozen game conflict; quarantine required'); END;

CREATE TRIGGER "game_period_scores_frozen_conflict" BEFORE INSERT ON game_period_scores WHEN EXISTS(SELECT 1 FROM game_state_observations WHERE game_id=NEW.game_id AND is_final=1) AND EXISTS(SELECT 1 FROM game_period_scores old WHERE old."game_id"=NEW."game_id" AND old."team_id"=NEW."team_id" AND old."period_index"=NEW."period_index" AND ((old."period_points" IS NOT NULL AND NEW."period_points" IS NOT NULL AND old."period_points"<>NEW."period_points"))) BEGIN SELECT RAISE(ABORT,'frozen game conflict; quarantine required'); END;

CREATE TRIGGER "game_state_observations_frozen_conflict" BEFORE INSERT ON game_state_observations WHEN EXISTS(SELECT 1 FROM game_state_observations WHERE game_id=NEW.game_id AND is_final=1) AND EXISTS(SELECT 1 FROM game_state_observations old WHERE old."game_id"=NEW."game_id" AND ((old."status_code" IS NOT NULL AND NEW."status_code" IS NOT NULL AND old."status_code"<>NEW."status_code") OR (old."home_points" IS NOT NULL AND NEW."home_points" IS NOT NULL AND old."home_points"<>NEW."home_points") OR (old."away_points" IS NOT NULL AND NEW."away_points" IS NOT NULL AND old."away_points"<>NEW."away_points") OR (old."overtime_count" IS NOT NULL AND NEW."overtime_count" IS NOT NULL AND old."overtime_count"<>NEW."overtime_count") OR (old."attendance" IS NOT NULL AND NEW."attendance" IS NOT NULL AND old."attendance"<>NEW."attendance") OR (old."was_simulated" IS NOT NULL AND NEW."was_simulated" IS NOT NULL AND old."was_simulated"<>NEW."was_simulated") OR (old."score_provenance" IS NOT NULL AND NEW."score_provenance" IS NOT NULL AND old."score_provenance"<>NEW."score_provenance") OR (old."is_final" IS NOT NULL AND NEW."is_final" IS NOT NULL AND old."is_final"<>NEW."is_final"))) BEGIN SELECT RAISE(ABORT,'frozen game conflict; quarantine required'); END;

CREATE TRIGGER "identity_player_fk" BEFORE INSERT ON native_identity_links WHEN NEW.entity_type='player' AND NOT EXISTS(SELECT 1 FROM players WHERE player_id=NEW.entity_id) BEGIN SELECT RAISE(ABORT,'unresolved native identity'); END;

CREATE TRIGGER "identity_team_fk" BEFORE INSERT ON native_identity_links WHEN NEW.entity_type='team' AND NOT EXISTS(SELECT 1 FROM teams WHERE team_id=NEW.entity_id) BEGIN SELECT RAISE(ABORT,'unresolved native identity'); END;

CREATE TRIGGER "identity_game_fk" BEFORE INSERT ON native_identity_links WHEN NEW.entity_type='game' AND NOT EXISTS(SELECT 1 FROM games WHERE game_id=NEW.entity_id) BEGIN SELECT RAISE(ABORT,'unresolved native identity'); END;

CREATE TRIGGER "identity_staff_fk" BEFORE INSERT ON native_identity_links WHEN NEW.entity_type='staff' AND NOT EXISTS(SELECT 1 FROM staff_members WHERE staff_id=NEW.entity_id) BEGIN SELECT RAISE(ABORT,'unresolved native identity'); END;

CREATE TRIGGER "player_season_totals_final_once" BEFORE INSERT ON player_season_totals WHEN EXISTS (SELECT 1 FROM player_season_totals WHERE player_id=NEW.player_id AND season_id=NEW.season_id AND is_final=1) OR EXISTS(SELECT 1 FROM season_finalizations WHERE season_id=NEW.season_id) BEGIN SELECT RAISE(ABORT,'season totals already finalized; quarantine conflict'); END;

CREATE TRIGGER "team_season_totals_final_once" BEFORE INSERT ON team_season_totals WHEN EXISTS (SELECT 1 FROM team_season_totals WHERE team_id=NEW.team_id AND season_id=NEW.season_id AND is_final=1) OR EXISTS(SELECT 1 FROM season_finalizations WHERE season_id=NEW.season_id) BEGIN SELECT RAISE(ABORT,'season totals already finalized; quarantine conflict'); END;

CREATE VIEW gm_player_observations AS SELECT p.player_id,p.display_name,a.*,u.observed_at,r.source_grade FROM player_attribute_snapshots a JOIN players p USING(player_id) JOIN capture_units u USING(unit_id) JOIN capture_runs r USING(run_id) WHERE u.unit_status='success';

CREATE VIEW gm_game_box AS SELECT g.game_id,g.season_id,g.game_date,p.display_name,b.*,u.observed_at,r.source_grade FROM player_game_boxes b JOIN games g USING(game_id) JOIN players p USING(player_id) JOIN capture_units u USING(unit_id) JOIN capture_runs r USING(run_id) WHERE u.unit_status='success';

CREATE VIEW derived_game_scores AS SELECT game_id,unit_id,team_id,SUM(period_points) AS regulation_points,'DERIVED_SUM_PERIODS' AS provenance FROM game_period_scores GROUP BY game_id,unit_id,team_id;

CREATE VIEW derived_player_box_metrics AS SELECT box_id,CASE WHEN fg_attempted>0 THEN 1.0*(fg_made+0.5*three_made)/fg_attempted END AS efg_pct,CASE WHEN fg_attempted+0.44*ft_attempted>0 THEN points/(2.0*(fg_attempted+0.44*ft_attempted)) END AS ts_pct,'DERIVED_WITH_FORMULA_V1' AS provenance FROM player_game_boxes;
